// Generated by bench/emoji/build-unicode.mjs: "shortcode<TAB>emoji" per line. Loaded on demand by the composer, never at startup.
export type Standard = { name: string; char: string };
const UNICODE_LIMIT = 8;

/** Standard emoji by shortcode from the table: names starting with the query first, then names containing it. */
export function suggestStandard(query: string): Standard[] {
  const found: Standard[] = [], rest: Standard[] = [];
  for (const line of TABLE.split('\n')) {
    const tab = line.indexOf('\t'), name = line.slice(0, tab);
    if (name.startsWith(query)) found.push({ name, char: line.slice(tab + 1) });
    else if (query.length > 1 && name.includes(query)) rest.push({ name, char: line.slice(tab + 1) });
  }
  return [...found, ...rest].slice(0, UNICODE_LIMIT);
}

